#!/usr/bin/env bash
# Close PRs listed in .pr-close-list.txt (generated by audit-prs.sh)
# Usage:
#   ./scripts/close-prs.sh              # execute closes
#   ./scripts/close-prs.sh --dry-run    # preview only

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
CLOSE_LIST="$REPO_ROOT/.pr-close-list.txt"
DRY_RUN=false
CLOSE_COMMENT="Closing as part of automated audit: no human engagement, CI not passing, and/or merge conflicts. Please reopen or submit a fresh PR if this fix is still needed against latest main."

if [[ "${1:-}" == "--dry-run" ]]; then
  DRY_RUN=true
  echo "[DRY RUN] No PRs will be closed."
fi

if [[ ! -f "$CLOSE_LIST" ]]; then
  echo "Error: $CLOSE_LIST not found. Run audit-prs.sh first."
  exit 1
fi

TOTAL=$(wc -l < "$CLOSE_LIST" | tr -d ' ')
echo "PRs to close: $TOTAL"

if [[ "$TOTAL" -eq 0 ]]; then
  echo "Nothing to close."
  exit 0
fi

CLOSED=0
FAILED=0

while IFS= read -r number; do
  [[ -z "$number" ]] && continue
  if "$DRY_RUN"; then
    echo "[DRY RUN] Would close PR #$number"
  else
    if gh pr close "$number" --comment "$CLOSE_COMMENT" 2>/dev/null; then
      echo "Closed #$number"
      CLOSED=$((CLOSED + 1))
    else
      echo "Warning: failed to close #$number (may already be closed or insufficient permissions)"
      FAILED=$((FAILED + 1))
    fi
    # Rate-limit courtesy pause
    sleep 0.3
  fi
done < "$CLOSE_LIST"

if ! "$DRY_RUN"; then
  echo ""
  echo "Done. Closed: $CLOSED  Failed: $FAILED"
fi
